async function clickIfVisible(testId, failures, options = {}) {
    const clickTimeout = typeof options.timeout === 'number' ? options.timeout : DEFAULT_CLICK_TIMEOUT_MS;
    const target = page.getByTestId(testId);
    if (await target.count()) {
        try {
            if (!options.skipPreDismiss) {
                const dBudget = typeof options.dismissBudgetMs === 'number' ? options.dismissBudgetMs : 15000;
                await dismissBlockingOverlays({ budgetMs: dBudget });
            }
            const el = target.first();
            await el.waitFor({ state: 'visible', timeout: clickTimeout }).catch(() => {});
            await el.scrollIntoViewIfNeeded().catch(() => {});
            await el.click({
                timeout: clickTimeout,
                force: Boolean(options.force),
                noWaitAfter: true,
            });
            await page.waitForTimeout(120);
            return true;
        } catch (err) {
            failures.push(`${testId}: ${err && err.message ? err.message : String(err)}`);
        }
    }
    return false;
}

input.new_string:
async function clickIfVisible(testId, failures, options = {}) {
    const clickTimeout = typeof options.timeout === 'number' ? options.timeout : DEFAULT_CLICK_TIMEOUT_MS;
    const target = page.getByTestId(testId);
    if (await target.count()) {
        try {
            if (!options.skipPreDismiss) {
                const dBudget = typeof options.dismissBudgetMs === 'number' ? options.dismissBudgetMs : 15000;
                await dismissBlockingOverlays({ budgetMs: dBudget });
            }
            const el = target.first();
            await el.waitFor({ state: 'visible', timeout: clickTimeout }).catch(() => {});
            await el.scrollIntoViewIfNeeded().catch(() => {});

            const tryNormal = async () => el.click({
                timeout: clickTimeout,
                force: Boolean(options.force),
                noWaitAfter: true,
            });
            const tryForce = async () => el.click({
                timeout: Math.min(clickTimeout, 15000),
                force: true,
                noWaitAfter: true,
            });
            const tryEvalClick = async () => {
                const ok = await page.evaluate((id) => {
                    const node = document.querySelector(`[data-testid="${id}"]`);
                    if (!node) return false;
                    node.scrollIntoView({ block: 'center', inline: 'center' });
                    node.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
                    return true;
                }, testId);
                if (!ok) throw new Error('clickIfVisible: no node for data-testid');
            };

            try {
                await tryNormal();
            } catch (e1) {
                if (!options.force) {
                    try {
                        await tryForce();
                    } catch (e2) {
                        await tryEvalClick();
                    }
                } else {
                    await tryEvalClick();
                }
            }
            await page.waitForTimeout(120);
            return true;
        } catch (err) {
            failures.push(`${testId}: ${err && err.message ? err.message : String(err)}`);
        }
    }
    return false;
}

