/**
 * Close a Playwright ElectronApplication without wedging the worker teardown (Windows can ignore soft kills).
 * @param {import('playwright').ElectronApplication|null|undefined} app
 * @param {number} [closeTimeoutMs]
 */
async function closeElectronApp(app, closeTimeoutMs = 12000) {
    if (!app) return;
    try {
        await Promise.race([
            app.close(),
            new Promise((_, reject) => {
                setTimeout(() => reject(new Error('close_timeout')), closeTimeoutMs);
            }),
        ]);
    } catch {
        try {
            const proc = typeof app.process === 'function' ? app.process() : null;
            if (proc && !proc.killed) {
                try {
                    proc.kill('SIGKILL');
                } catch {
                    try {
                        proc.kill();
                    } catch {
                        /* ignore */
                    }
                }
            }
        } catch {
            /* ignore */
        }
    }
}

module.exports = {
    ONBOARDING_PROGRESS_DEFAULT,
    installE2EProfileInitScript,
    reloadAndAssertMainShell,
    closeElectronApp,
