    if (!app) return;
    // Playwright runs suite afterAll twice on failure (After Hooks + Worker Cleanup). A second
    // close on a dead ElectronApplication can hang until the worker teardown slot expires.
    const hardCapMs = Math.min(60000, Math.max(22000, closeTimeoutMs + 12000));
    try {
        await Promise.race([
            (async () => {
                try {
                    if (typeof app.windows === 'function') {
                        const wins = app.windows();
                        for (let i = wins.length - 1; i >= 0; i -= 1) {
                            const w = wins[i];
                            try {
                                if (w && !w.isClosed()) {
