                                    await Promise.race([
                                        w.close({ runBeforeUnload: false }),
                                        new Promise((_, reject) => {
                                            setTimeout(() => reject(new Error('page_close_timeout')), 5000);
                                        }),
                                    ]).catch(() => {});
                                }
                            } catch {
                                /* ignore */
                            }
                        }
                    }
                } catch {
                    /* ignore */
                }
                try {
                    await Promise.race([
                        app.close(),
                        new Promise((_, reject) => {
                            setTimeout(() => reject(new Error('close_timeout')), closeTimeoutMs);
                        }),
                    ]);
                } catch {
                    forceKillElectronProcess(app);
                }
            })(),
            new Promise((_, reject) => {
                setTimeout(() => reject(new Error('close_electron_hard_cap')), hardCapMs);
            }),
        ]);
    } catch {
        forceKillElectronProcess(app);
    }
