/**
 * Runs electron-builder. On Windows, passes a local unpacked Electron dist
 * (--config.electronDist) so packaging does not rely only on the builder cache,
 * where Defender often removes electron.exe before the rename step.
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { Readable } from 'node:stream';
import { createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

function electronBuilderBin() {
  const ext = process.platform === 'win32' ? '.cmd' : '';
  const p = path.join(root, 'node_modules', '.bin', `electron-builder${ext}`);
  return fs.existsSync(p) ? p : null;
}

async function ensureWinElectronDist() {
  if (process.platform !== 'win32' || process.arch !== 'x64') {
    throw new Error('ensureWinElectronDist: expected win32 x64');
  }
  const epkg = path.join(root, 'node_modules', 'electron', 'package.json');
  if (!fs.existsSync(epkg)) {
    throw new Error('node_modules/electron missing; run npm ci');
  }
  const { version } = JSON.parse(fs.readFileSync(epkg, 'utf8'));
  const outDir = path.join(root, 'vendor', 'electron-dist-cache', `win32-x64-${version}`);
  const marker = path.join(outDir, 'electron.exe');
  if (fs.existsSync(marker)) {
    return outDir;
  }

  fs.mkdirSync(outDir, { recursive: true });
  for (const name of fs.readdirSync(outDir)) {
    fs.rmSync(path.join(outDir, name), { recursive: true, force: true });
  }

  const url = `https://github.com/electron/electron/releases/download/v${version}/electron-v${version}-win32-x64.zip`;
  const zipPath = path.join(outDir, 'download.zip');
  // eslint-disable-next-line no-console -- build diagnostics
  console.error(
    `[run-electron-builder] Caching Electron ${version} win32-x64 under vendor/electron-dist-cache (Windows build workaround).\n`,
  );
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`GET ${url} -> ${res.status} ${res.statusText}`);
  }
  await pipeline(Readable.fromWeb(res.body), createWriteStream(zipPath));

  const tar = spawnSync('tar', ['-xf', zipPath, '-C', outDir], {
    stdio: 'inherit',
    cwd: root,
  });
  if (tar.error) {
    throw tar.error;
  }
  if (tar.status !== 0) {
    throw new Error(`tar extract failed with exit ${tar.status}`);
  }
  fs.unlinkSync(zipPath);

  if (!fs.existsSync(marker)) {
    throw new Error(`electron.exe missing after extract: ${outDir}`);
  }
  return outDir;
}

const bin = electronBuilderBin();
if (!bin) {
  // eslint-disable-next-line no-console -- build diagnostics
  console.error('electron-builder not found in node_modules/.bin; run npm ci.');
  process.exit(1);
}

const forward = process.argv.slice(2);
const prefix = [];
if (process.platform === 'win32' && process.arch === 'x64') {
  const distDir = await ensureWinElectronDist();
  prefix.push(`--config.electronDist=${distDir.replace(/\\/g, '/')}`);
}

const r = spawnSync(bin, [...prefix, ...forward], {
  stdio: 'inherit',
  cwd: root,
  env: process.env,
  shell: process.platform === 'win32',
});

process.exit(r.status === null ? 1 : r.status);

