import { Agent, fetch as undiciFetch } from 'undici';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/** Long timeouts + large headers; release zips are ~100MB+ over HTTPS. */
const downloadAgent = new Agent({
  connectTimeout: 120_000,
  headersTimeout: 120_000,
  bodyTimeout: 600_000,
});

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Download with HTTP Range resume (GitHub release assets support Range).
 * Retries on socket drops and truncated files.
 */
async function downloadElectronZip(url, zipPath) {
  const maxPasses = 12;
  for (let pass = 0; pass < maxPasses; pass++) {
    const start = fs.existsSync(zipPath) ? fs.statSync(zipPath).size : 0;
    const headers = start > 0 ? { Range: `bytes=${start}-` } : {};
    let res;
    try {
      res = await undiciFetch(url, { dispatcher: downloadAgent, headers });
    } catch (err) {
      if (pass === maxPasses - 1) {
        throw err;
      }
      const delay = Math.min(90_000, 2500 * 2 ** Math.min(pass, 5));
      console.error(
        `[run-electron-builder] Network error (${err.cause?.code ?? err.message}); retry in ${Math.round(delay / 1000)}s…`,
      );
      await sleep(delay);
      continue;
    }

    if (res.status === 416 && start > 0) {
      fs.unlinkSync(zipPath);
      continue;
    }
    if (!res.ok) {
      throw new Error(`GET ${url} -> ${res.status} ${res.statusText}`);
    }

    if (res.status === 206) {
      await pipeline(Readable.fromWeb(res.body), createWriteStream(zipPath, { flags: 'a' }));
    } else if (res.status === 200) {
      if (start > 0) {
        fs.unlinkSync(zipPath);
      }
      await pipeline(Readable.fromWeb(res.body), createWriteStream(zipPath));
    } else {
      throw new Error(`Unexpected HTTP status ${res.status}`);
    }

    const total = parseTotalBytes(res.headers.get('content-range'));
    const got = fs.statSync(zipPath).size;
    if (total != null && got < total) {
      if (pass === maxPasses - 1) {
        throw new Error(`Download still incomplete after retries (${got}/${total} bytes)`);
      }
      const delay = Math.min(60_000, 2000 * 2 ** Math.min(pass, 4));
      console.error(
        `[run-electron-builder] Partial zip (${got}/${total} bytes); resuming in ${Math.round(delay / 1000)}s…`,
      );
      await sleep(delay);
      continue;
    }

    const probe = spawnSync('tar', ['-tf', zipPath], { encoding: 'utf8' });
    if (probe.status !== 0 || !probe.stdout.includes('electron.exe')) {
      fs.unlinkSync(zipPath);
      if (pass === maxPasses - 1) {
        throw new Error('Downloaded file is not a valid Electron zip (electron.exe missing in archive)');
      }
      console.error('[run-electron-builder] Zip corrupt or incomplete; re-downloading…');
      await sleep(3000);
      continue;
    }
    return;
  }
}

function parseTotalBytes(contentRange) {
  if (!contentRange) {
    return null;
  }
  const m = /\/(\d+)\s*$/.exec(contentRange);
  return m ? Number(m[1]) : null;
}

