  "node tear/llm-connections.test.js",
];

function main() {
  const n = STEPS.length;
  for (let i = 0; i < n; i++) {
    const cmd = STEPS[i];
    const label = `[test ${i + 1}/${n}]`;
    process.stderr.write(`${label} ${cmd}\n`);
    try {
      execSync(cmd, { cwd: root, stdio: "inherit", env: process.env });
