/** Small DOM snapshot for CI log printing (first ~200 lines of offline-kill-compact.json). */
async function compactOfflineKillSnapshot(pg = page) {
    return pg
        .evaluate(() => {
            const read = (selector) => {
                const el = document.querySelector(selector);
                if (!el) return { exists: false };
                const rect = el.getBoundingClientRect();
                const style = getComputedStyle(el);
                return {
                    exists: true,
                    text: (el.textContent || '').trim().slice(0, 300),
                    value: 'value' in el ? el.value : undefined,
                    disabled: Boolean(el.disabled),
                    display: style.display,
                    visibility: style.visibility,
                    opacity: style.opacity,
                    pointerEvents: style.pointerEvents,
                    rect: {
                        x: Math.round(rect.x),
                        y: Math.round(rect.y),
                        width: Math.round(rect.width),
                        height: Math.round(rect.height),
                    },
                };
            };

            return {
                url: location.href,
                drawer: read('[data-testid="settings-drawer"]'),
                connectionTab: read('[data-testid="settings-tab-connection"]'),
                connectionPanel: read('[data-testid="settings-panel-connection"]'),
                controls: read('[data-testid="settings-connection-controls"]'),
                provider: read('[data-testid="settings-provider-select"]'),
                kill: read('[data-testid="settings-offline-kill-btn"]'),
                status: read('[data-testid="settings-status-text"]'),
                close: read('[data-testid="settings-close-btn"]'),
                bodyNeedles: {
                    hasGoOffline: document.body.innerText.includes('Go Offline'),
                    hasApplying: document.body.innerText.includes('Applying offline kill switch'),
                    hasEngaged: document.body.innerText.includes('Offline kill switch engaged'),
                    hasFailed: document.body.innerText.includes('Offline kill switch failed'),
                    hasOpenRouter: document.body.innerText.includes('OpenRouter'),
                    hasOllama: document.body.innerText.includes('Ollama'),
                },
            };
        })
        .catch((err) => ({ error: err?.message || String(err) }));
}

async function writeOfflineKillCompactFile(pg, label) {
    const snap = await compactOfflineKillSnapshot(pg);
    const payload = { label, at: new Date().toISOString(), ...snap };
    const outPath = test.info().outputPath('offline-kill-compact.json');
    await fs.promises.writeFile(outPath, JSON.stringify(payload, null, 2), 'utf8');
}

