                    ariaHidden: el.getAttribute('aria-hidden'),
                    rect: rectBox(el),
                    text: norm(el.textContent || ''),
                };
            };

            const namedPatterns = [
                { key: 'connection', re: /connection/i },
                { key: 'connections', re: /connections/i },
                { key: 'providers', re: /providers/i },
                { key: 'models', re: /models/i },
                { key: 'api', re: /\bapi\b/i },
                { key: 'settings', re: /settings/i },
            ];
            const namedMatches = {};
            namedPatterns.forEach(({ key }) => {
                namedMatches[key] = [];
            });

            const drawers = Array.from(document.querySelectorAll('[data-testid="settings-drawer"]'));
            const openDrawers = drawers.filter((d) => d.getAttribute('data-state') === 'open');
            const drawerSummaries = openDrawers.map((d, i) => ({
                index: i,
                dataState: d.getAttribute('data-state'),
                dataReady: d.getAttribute('data-ready'),
                ariaModal: d.getAttribute('aria-modal'),
                ariaHidden: d.getAttribute('aria-hidden'),
                textSample: norm(d.innerText || '').slice(0, 2500),
            }));

            const tabButtons = [];
            openDrawers.forEach((drawer, di) => {
                drawer.querySelectorAll('[data-settings-tab]').forEach((btn) => {
                    const text = norm(btn.textContent || '');
                    const entry = { drawerIndex: di, ...describeEl(btn) };
                    tabButtons.push(entry);
                    namedPatterns.forEach(({ key, re }) => {
                        if (re.test(text)) namedMatches[key].push(entry);
                    });
                });
            });

            const roleTabs = [];
            openDrawers.forEach((drawer, di) => {
                drawer.querySelectorAll('[role="tab"]').forEach((el) => {
                    roleTabs.push({ drawerIndex: di, ...describeEl(el) });
                });
            });

            const openDrawer = openDrawers[0] || null;
            const connectionTabEl = openDrawer
                ? openDrawer.querySelector('[data-testid="settings-tab-connection"]')
                : null;
            const connectionPanelEl = openDrawer
                ? openDrawer.querySelector('[data-testid="settings-panel-connection"]')
                : null;
            const controlsEl = openDrawer
                ? openDrawer.querySelector('[data-testid="settings-connection-controls"]')
                : null;
            const providerEl = openDrawer
                ? openDrawer.querySelector('[data-testid="settings-provider-select"]')
                : null;

            const ae = document.activeElement;
            const activeElement =
                ae instanceof Element
                    ? {
                          tag: ae.tagName,
                          id: norm(ae.id),
                          dataTestId: ae.getAttribute('data-testid') || '',
                          dataSettingsTab: ae.getAttribute('data-settings-tab') || '',
                          ariaLabel: norm(ae.getAttribute('aria-label') || ''),
                          role: ae.getAttribute('role') || '',
                      }
                    : null;

            const mobileIndicators = {
                innerWidthLtSmTailwind: window.innerWidth < 640,
                innerWidthLtMd: window.innerWidth < 768,
                touchPoints: typeof navigator.maxTouchPoints === 'number' ? navigator.maxTouchPoints : null,
            };

            return {
                ok: true,
                label: snapshotLabel,
                ts: Date.now(),
                url: location.href,
                viewport: {
                    width: window.innerWidth,
                    height: window.innerHeight,
                    devicePixelRatio: typeof window.devicePixelRatio === 'number' ? window.devicePixelRatio : null,
                },
                mobileIndicators,
                drawerCount: drawers.length,
                openDrawerCount: openDrawers.length,
                drawerSummaries,
                tabButtons,
                roleTabs,
                namedMatches,
                connectionTab: describeEl(connectionTabEl),
                connectionPanel: describeEl(connectionPanelEl),
                controls: describeEl(controlsEl),
                providerSelect: describeEl(providerEl),
                flags: {
                    connectionTabPresent: Boolean(connectionTabEl),
                    connectionTabActiveAttr:
                        connectionTabEl && connectionTabEl.getAttribute('data-active') === 'true',
                    connectionPanelPresent: Boolean(connectionPanelEl),
                    connectionPanelVisible: Boolean(connectionPanelEl && rectBox(connectionPanelEl)?.visible),
                    controlsPresent: Boolean(controlsEl),
                    controlsVisible: Boolean(controlsEl && rectBox(controlsEl)?.visible),
                    providerPresent: Boolean(providerEl),
                    providerVisible: Boolean(providerEl && rectBox(providerEl)?.visible),
                },
                activeElement,
            };
        }, { snapshotLabel: label });
    } catch (err) {
        return {
            ok: false,
            label,
            outerError: err && err.message ? err.message : String(err),
        };
    }
}

/**
 * Derive a single classification from before/after Connection-tab boundary snapshots.
 */
function classifyConnectionTabBoundary(beforeSnap, afterSnap) {
    const after = afterSnap && afterSnap.ok !== false ? afterSnap : beforeSnap;
    const flags = after && after.flags ? after.flags : {};
    const open = typeof after.openDrawerCount === 'number' ? after.openDrawerCount : 0;
    const connTab = after.connectionTab;

    if (open === 0) return 'settings-panel-wrong-state';
    if (!connTab || !connTab.tag) return 'connection-tab-missing';
    if (connTab.disabled) return 'connection-tab-disabled';
    if (connTab.rect && connTab.rect.visible === false) return 'compact-layout-tab-hidden';
    if (!flags.connectionTabActiveAttr) return 'connection-tab-click-not-committed';
    if (!flags.controlsPresent || !flags.providerPresent) return 'provider-controls-not-rendered-after-tab';
    if (!flags.controlsVisible || !flags.providerVisible) return 'provider-controls-not-rendered-after-tab';
    return 'connection-tab-ok';
}

