/** Rich DOM + storage slice for offline-kill downstream stage failures (post–Connection tab). */
async function offlineKillDownstreamDiagnostics(pg = page) {
    const compact = await compactOfflineKillSnapshot(pg);
    const extra = await pg
        .evaluate(() => {
            const norm = (s) => (typeof s === 'string' ? s.trim().slice(0, 200) : '');
            const storageMatches = (store) => {
                const rows = [];
                try {
                    for (let i = 0; i < store.length; i += 1) {
                        const key = String(store.key(i) || '');
                        const val = String(store.getItem(key) || '');
                        const blob = `${key} ${val}`.toLowerCase();
                        if (/(provider|openrouter|ollama|offline|local|kill|bridge|hosted|airgap|proxy|reconnect)/.test(blob)) {
                            rows.push({ key, value: val.slice(0, 400) });
                        }
                    }
                } catch {
                    /* ignore */
                }
                return rows;
            };
            const sel = document.querySelector('[data-testid="settings-provider-select"]');
            let providerOptions = [];
            if (sel && sel.options) {
                providerOptions = Array.from(sel.options).map((o) => ({
                    value: String(o.value || ''),
                    text: norm(o.text || ''),
                }));
            }
            const kill = document.querySelector('[data-testid="settings-offline-kill-btn"]');
            const panel = document.querySelector('[data-testid="settings-panel-connection"]');
            const statusEl = document.querySelector('[data-testid="settings-status-text"]');
            const ae = document.activeElement;
            const panelRect = panel instanceof Element ? panel.getBoundingClientRect() : null;
            const panelStyle = panel instanceof Element ? window.getComputedStyle(panel) : null;
            return {
                providerValue: sel && 'value' in sel ? String(sel.value || '') : '',
                providerOptions: providerOptions.slice(0, 32),
                kill: kill
                    ? {
                          text: norm(kill.textContent || ''),
                          disabled: Boolean(kill.disabled),
                          ariaDisabled: kill.getAttribute('aria-disabled'),
                      }
                    : null,
                statusText: statusEl ? norm(statusEl.textContent || '') : '',
                connectionPanel: panel
                    ? {
                          display: panelStyle ? panelStyle.display : '',
                          visibility: panelStyle ? panelStyle.visibility : '',
                          w: panelRect ? Math.round(panelRect.width) : 0,
                          h: panelRect ? Math.round(panelRect.height) : 0,
                      }
                    : null,
                bodyNeedles: {
                    engaged: /Offline kill switch engaged/i.test(document.body.innerText || ''),
                    failed: /Offline kill switch failed/i.test(document.body.innerText || ''),
                    applying: /Applying offline kill switch/i.test(document.body.innerText || ''),
                    localOnly: /local-only|local only|ollama/i.test(document.body.innerText || ''),
                },
                localStorageMatches: storageMatches(window.localStorage),
                sessionStorageMatches: storageMatches(window.sessionStorage),
                activeElement:
                    ae instanceof Element
                        ? {
                              tag: ae.tagName,
                              dataTestId: ae.getAttribute('data-testid') || '',
                              ariaLabel: norm(ae.getAttribute('aria-label') || ''),
                          }
                        : null,
                url: location.href,
                viewport: { width: window.innerWidth, height: window.innerHeight },
            };
        })
        .catch((err) => ({ evaluateError: err?.message || String(err) }));
    return { compact, downstream: extra };
}

/**
 * Bounded stage wrapper: always writes before/after or failed JSON under `offline-kill-stage-*`
 * so CI never dies at 300s without naming the hung downstream stage.
 */
async function withOfflineKillStage(
    pg,
    stageName,
    timeoutMs,
    classificationTimeout,
    classificationFailed,
    fn,
    options = {},
) {
    const fileBase = `offline-kill-stage-${stageName}`;
    const started = Date.now();
    await attachJsonSnapshot(`${fileBase}-before.json`, {
        stageName,
        classification: 'stage-pending',
        ts: started,
        timeoutMs,
        ...(await offlineKillDownstreamDiagnostics(pg)),
    });

    let timerId;
    let timedOut = false;
    const timeoutPromise = new Promise((_, reject) => {
        timerId = setTimeout(() => {
            timedOut = true;
            reject(new Error(`[offline-kill-stage] ${stageName} exceeded ${timeoutMs}ms`));
        }, timeoutMs);
    });

    try {
        await Promise.race([fn(), timeoutPromise]);
    } catch (err) {
        let classification = timedOut ? classificationTimeout : classificationFailed;
        if (typeof options.resolveClassification === 'function') {
            try {
                const c = options.resolveClassification(err, timedOut);
                if (typeof c === 'string' && c.length) classification = c;
            } catch {
                /* keep default */
            }
        }
        const elapsedMs = Date.now() - started;
        const diag = await offlineKillDownstreamDiagnostics(pg);
        let extra = {};
        if (typeof options.extraFailureFields === 'function') {
            try {
                extra = await options.extraFailureFields();
            } catch {
                extra = { extraFailureFieldsError: true };
            }
        }
        await attachJsonSnapshot(`${fileBase}-failed.json`, {
            stageName,
            classification,
            timedOut,
            errorName: err && err.name ? err.name : '',
            errorMessage: err && err.message ? err.message : String(err),
            elapsedMs,
            ...diag,
            ...extra,
        });
        appendOfflineKillCiSummary(
            `- **offline-kill-stage** \`${stageName}\` **${classification}** (${elapsedMs}ms) ${err && err.message ? err.message : String(err)}`,
        );
        throw err;
    } finally {
        clearTimeout(timerId);
    }

    const elapsedMs = Date.now() - started;
    await attachJsonSnapshot(`${fileBase}-after.json`, {
        stageName,
        classification: 'stage-ok',
        elapsedMs,
        ...(await offlineKillDownstreamDiagnostics(pg)),
    });
    appendOfflineKillCiSummary(`- **offline-kill-stage** \`${stageName}\` **stage-ok** (${elapsedMs}ms)`);
}

