    appendOfflineKillCiSummary('- **phase** acquiring Go Offline button');
    await withCompactOfflineKillDiagnostics('kill-waitfor-visible-failed', async () => {
        await page.waitForSelector(
            '[data-testid="settings-drawer"][data-state="open"] [data-testid="settings-offline-kill-btn"]',
            { state: 'visible', timeout: PHASE_MS },
        );
    });

    // Do not call dismissBlockingOverlays here: its generic backdrop locator matches the
    // Settings drawer scrim (fixed inset-0 z-40 bg-black/40) and closes the drawer before click.
    const killBtn = await getOfflineKillButton(connectionPanelKill, controlsAfterProvider);
    await killBtn.scrollIntoViewIfNeeded().catch(() => {});
