    await attachJsonSnapshot('settings-before-kill-after-provider.json', preKillSnap2);
    appendOfflineKillCiSummary('- **phase** kill button pre-click compact');
    await attachJsonSnapshot(
        'offline-kill-compact-before-kill-visible.json',
        await compactOfflineKillSnapshot(page),
    );
    await attachJsonSnapshot(
        'offline-kill-compact-before-click.json',
        await compactOfflineKillSnapshot(page),
    );

    appendOfflineKillCiSummary('- **phase** kill button visibility');
    await withCompactOfflineKillDiagnostics('kill-visible-failed', async () => {
        await killBtn.scrollIntoViewIfNeeded().catch(() => {});
        await page.waitForTimeout(250);
        await expect(killBtn).toBeVisible({ timeout: PHASE_MS });
    });
    appendOfflineKillCiSummary('- **phase** kill button enabled check');
    await withCompactOfflineKillDiagnostics('kill-enabled-failed', async () => {
        await expect(killBtn).toBeEnabled({ timeout: PHASE_MS });
    });

    appendOfflineKillCiSummary('- **phase** clicking Go Offline');
    // eslint-disable-next-line no-console -- may appear in some reporters; Summary uses appendOfflineKillCiSummary
