        'offline-kill-compact-after-click.json',
        await compactOfflineKillSnapshot(page),
    );

    appendOfflineKillCiSummary('- **phase** waiting for offline-kill status');
    await withCompactOfflineKillDiagnostics('status-wait-failed', async () => {
        const startedAt = Date.now();
        let lastOfflineKillSnapshot = null;
        let lastCompact = null;
        const finalCompactPath = test.info().outputPath('offline-kill-compact-final.json');
        while (Date.now() - startedAt < OFFLINE_KILL_POST_CLICK_WAIT_MS) {
            lastCompact = await compactOfflineKillSnapshot(page);
            await fs.promises.writeFile(finalCompactPath, JSON.stringify(lastCompact, null, 2), 'utf8');
            lastOfflineKillSnapshot = await page
                .evaluate(() => {
                    const status =
                        document.querySelector('[data-testid="settings-status-text"]')?.textContent?.trim() || '';
                    const provider = document.querySelector('[data-testid="settings-provider-select"]')?.value || '';
                    const kill = document.querySelector('[data-testid="settings-offline-kill-btn"]');
                    return {
                        status,
                        provider,
                        killPresent: Boolean(kill),
                        killDisabled: Boolean(kill?.disabled),
                    };
