                .catch((err) => ({ error: err?.message || String(err) }));

            if (lastOfflineKillSnapshot && lastOfflineKillSnapshot.error) {
                break;
            }
            if (/Offline kill switch engaged/i.test(lastOfflineKillSnapshot.status)) {
                break;
            }
            if (/Offline kill switch failed/i.test(lastOfflineKillSnapshot.status)) {
                await attachJsonSnapshot('offline-kill-compact-final.json', lastCompact);
                await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
                appendOfflineKillCiSummary(`- **kill_failed** ${JSON.stringify(lastOfflineKillSnapshot)}`);
                throw new Error(
