        await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
        if (!lastOfflineKillSnapshot || lastOfflineKillSnapshot.error) {
            throw new Error(
                `[offline-kill-ci] could not read status after click: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
            );
