await test.step('force local-only posture (OpenRouter then Go Offline)', async () => {
    /** Per-stage wall clocks: fail with `offline-kill-stage-*-failed.json` before whole-test 300s timeout. */
    const STAGE_PHASE_MS = 24000;
    const STAGE_PROVIDER_SELECT_MS = 52000;
    const STAGE_ENSURE_PANEL_MS = 32000;
    const STAGE_KILL_VISIBLE_MS = 32000;
    const STAGE_KILL_CLICK_MS = 20000;
    const STAGE_POSTURE_WAIT_MS = 75000;
    const STAGE_RESET_OLLAMA_MS = 28000;

    appendOfflineKillCiSummary('- **phase** force-local start');
    await attachJsonSnapshot(
        'offline-kill-compact-force-start.json',
        await compactOfflineKillSnapshot(page),
    );

    const drawer = await getActiveSettingsDrawer();
    const connectionPanel = drawer.getByTestId('settings-panel-connection');
    const controls = connectionPanel.getByTestId('settings-connection-controls');
    await withCompactOfflineKillDiagnostics('controls-visible-failed', async () => {
        await withReadinessDiagnostics(async () => {
            await expect(controls).toBeVisible({ timeout: STAGE_PHASE_MS });
        });
    });
    await controls.scrollIntoViewIfNeeded().catch(() => {});

    const providerSelect = controls.getByTestId('settings-provider-select');
    await providerSelect.scrollIntoViewIfNeeded().catch(() => {});
    await withCompactOfflineKillDiagnostics('provider-visible-failed', async () => {
        await withReadinessDiagnostics(async () => {
            await expect(providerSelect).toBeVisible({ timeout: STAGE_PHASE_MS });
        });
    });
    await page.waitForTimeout(200);

    appendOfflineKillCiSummary('- **phase** checking openrouter lane availability');
    const hasOpenRouter = await page.evaluate(() => {
        const box = document.querySelector('[data-testid="settings-connection-controls"]');
        const el = box && box.querySelector('[data-testid="settings-provider-select"]');
        if (!el) return false;
        return [...el.options].some((o) => String(o.value) === 'openrouter');
    });
    if (!hasOpenRouter) {
        await connectionPanel.getByTestId('settings-preset-openrouter-btn').click({ timeout: 8000 }).catch(() => {});
        await page.waitForTimeout(400);
    }
    const hasOpenRouterNow = await page.evaluate(() => {
        const box = document.querySelector('[data-testid="settings-connection-controls"]');
        const el = box && box.querySelector('[data-testid="settings-provider-select"]');
        if (!el) return false;
        return [...el.options].some((o) => String(o.value) === 'openrouter');
    });
    if (!hasOpenRouterNow) {
        test.skip(true, 'OpenRouter lane is unavailable in this build profile');
    }

    appendOfflineKillCiSummary('- **phase** selecting openrouter (bounded stage)');
    await withOfflineKillStage(
        page,
        'provider-select-openrouter',
        STAGE_PROVIDER_SELECT_MS,
        'provider-select-timeout',
        'provider-select-failed',
        async () => {
            await attachJsonSnapshot(
                'offline-kill-compact-before-openrouter-select.json',
                await compactOfflineKillSnapshot(page),
            );
            try {
                await selectProviderValue(controls, 'openrouter', {
                    phaseMs: STAGE_PHASE_MS,
                    label: 'provider-openrouter',
                });
            } catch (err) {
                appendOfflineKillCiSummary('- **retry** provider-openrouter after fresh controls');
                const refresh = await ensureConnectionPanel({
                    visibilityTimeout: STAGE_PHASE_MS,
                });
                const freshControls = refresh.controls;
                await attachJsonSnapshot(
                    'offline-kill-compact-provider-openrouter-retry.json',
                    await compactOfflineKillSnapshot(page),
                );
                await selectProviderValue(freshControls, 'openrouter', {
                    phaseMs: STAGE_PHASE_MS,
                    label: 'provider-openrouter-retry',
                });
            }
            await attachJsonSnapshot(
                'offline-kill-compact-after-openrouter-select.json',
                await compactOfflineKillSnapshot(page),
            );
        },
    );

    appendOfflineKillCiSummary('- **phase** openrouter value confirmed');
    const domAfterProvider = await offlineKillDomAfterProviderSnapshot();
    await attachJsonSnapshot('offline-kill-dom-after-provider.json', domAfterProvider);
    appendOfflineKillCiSummary('- **after-openrouter** (full dom JSON)');

    appendOfflineKillCiSummary('- **phase** ensuring connection panel after provider (bounded stage)');
    await page.waitForTimeout(400);
    await attachJsonSnapshot(
        'offline-kill-compact-before-ensure-panel.json',
        await compactOfflineKillSnapshot(page),
    );

    let connectionPanelKill;
    let controlsAfterProvider;
    let providerSelectAfter;
    await withOfflineKillStage(
        page,
        'ensure-panel-after-provider',
        STAGE_ENSURE_PANEL_MS,
        'ensure-panel-after-provider-timeout',
        'ensure-panel-after-provider-failed',
        async () => {
            const activeDrawerAfterProvider = await getDrawerWithProviderValue('openrouter', {
                timeout: STAGE_PHASE_MS,
            });
            const ensured = await ensureConnectionPanel({
                drawerSeed: activeDrawerAfterProvider,
                visibilityTimeout: STAGE_PHASE_MS,
            });
            connectionPanelKill = ensured.panel;
            controlsAfterProvider = ensured.controls;
            providerSelectAfter = controlsAfterProvider.getByTestId('settings-provider-select');
            await expect(providerSelectAfter).toHaveValue('openrouter', { timeout: STAGE_PHASE_MS });
            await attachJsonSnapshot(
                'offline-kill-compact-after-ensure-panel.json',
                await compactOfflineKillSnapshot(page),
            );
        },
    );

    appendOfflineKillCiSummary('- **phase** kill visible after provider (bounded stage)');
    const killBtn = await withOfflineKillStage(
        page,
        'kill-visible-after-provider',
        STAGE_KILL_VISIBLE_MS,
        'kill-visible-after-provider-timeout',
        'kill-visible-after-provider-failed',
        async () => {
            await page.waitForSelector(
                '[data-testid="settings-drawer"][data-state="open"] [data-testid="settings-offline-kill-btn"]',
                { state: 'visible', timeout: STAGE_PHASE_MS },
            );
            const btn = await getOfflineKillButton(connectionPanelKill, controlsAfterProvider);
            await btn.scrollIntoViewIfNeeded().catch(() => {});
            const preKillSnap2 = await settingsReadinessSnapshot();
            await attachJsonSnapshot('settings-before-kill-after-provider.json', preKillSnap2);
            appendOfflineKillCiSummary('- **phase** kill button pre-click compact');
            await attachJsonSnapshot(
                'offline-kill-compact-before-kill-visible.json',
                await compactOfflineKillSnapshot(page),
            );
            await attachJsonSnapshot(
                'offline-kill-compact-before-click.json',
                await compactOfflineKillSnapshot(page),
            );
            await btn.scrollIntoViewIfNeeded().catch(() => {});
            await page.waitForTimeout(250);
            await expect(btn).toBeVisible({ timeout: STAGE_PHASE_MS });
            await expect(btn).toBeEnabled({ timeout: STAGE_PHASE_MS });
            return btn;
        },
    );

    appendOfflineKillCiSummary('- **phase** clicking Go Offline (bounded stage)');
    // eslint-disable-next-line no-console -- may appear in some reporters; Summary uses appendOfflineKillCiSummary
    console.log('[offline-kill-ci] about to click Go Offline');
    await withOfflineKillStage(
        page,
        'kill-click',
        STAGE_KILL_CLICK_MS,
        'kill-click-timeout',
        'kill-click-failed',
        async () => {
            const statusBefore = await page
                .evaluate(
                    () =>
                        document
                            .querySelector('[data-testid="settings-status-text"]')
                            ?.textContent?.trim() || '',
                )
                .catch(() => '');
            await killBtn.click({ timeout: 18000, noWaitAfter: true });
            await page.waitForTimeout(2800);
            const statusAfter = await page
                .evaluate(
                    () =>
                        document
                            .querySelector('[data-testid="settings-status-text"]')
                            ?.textContent?.trim() || '',
                )
                .catch(() => '');
            if (
                !/Applying offline kill switch|Offline kill switch engaged|Offline kill switch failed/i.test(
                    statusAfter,
                )
            ) {
                const err = new Error(
                    `[offline-kill-stage] kill-click-not-committed statusBefore=${JSON.stringify(statusBefore)} statusAfter=${JSON.stringify(statusAfter)}`,
                );
                err.offlineKillClassification = 'kill-click-not-committed';
                throw err;
            }
            await attachJsonSnapshot(
                'offline-kill-compact-after-click.json',
                await compactOfflineKillSnapshot(page),
            );
        },
        {
            resolveClassification: (err, timedOut) => {
                if (timedOut) return 'kill-click-timeout';
                if (err && err.offlineKillClassification === 'kill-click-not-committed') {
                    return 'kill-click-not-committed';
                }
                return 'kill-click-failed';
            },
        },
    );

    appendOfflineKillCiSummary('- **phase** waiting for offline-kill status (bounded stage + poll samples)');
    const posturePoll = { samples: [] };
    await withOfflineKillStage(
        page,
        'post-click-posture-wait',
        STAGE_POSTURE_WAIT_MS,
        'post-click-posture-timeout',
        'post-click-posture-failed',
        async () => {
            const startedAt = Date.now();
            let lastOfflineKillSnapshot = null;
            let lastCompact = null;
            let nextSampleAt = 0;
            const finalCompactPath = test.info().outputPath('offline-kill-compact-final.json');
            while (Date.now() - startedAt < STAGE_POSTURE_WAIT_MS) {
                const elapsed = Date.now() - startedAt;
                if (elapsed >= nextSampleAt) {
                    nextSampleAt += 3000;
                    const mini = await page
                        .evaluate(() => {
                            const status =
                                document
                                    .querySelector('[data-testid="settings-status-text"]')
                                    ?.textContent?.trim() || '';
                            const provider =
                                document.querySelector('[data-testid="settings-provider-select"]')
                                    ?.value || '';
                            const kill = document.querySelector('[data-testid="settings-offline-kill-btn"]');
                            return {
                                status: status.slice(0, 220),
                                provider,
                                killPresent: Boolean(kill),
                                killDisabled: Boolean(kill?.disabled),
                            };
                        })
                        .catch((err) => ({ error: err?.message || String(err) }));
                    posturePoll.samples.push({ elapsedMs: elapsed, ...mini });
                }

                lastCompact = await compactOfflineKillSnapshot(page);
                await fs.promises.writeFile(finalCompactPath, JSON.stringify(lastCompact, null, 2), 'utf8');
                lastOfflineKillSnapshot = await page
                    .evaluate(() => {
                        const status =
                            document.querySelector('[data-testid="settings-status-text"]')?.textContent?.trim() || '';
                        const provider =
                            document.querySelector('[data-testid="settings-provider-select"]')?.value || '';
                        const kill = document.querySelector('[data-testid="settings-offline-kill-btn"]');
                        return {
                            status,
                            provider,
                            killPresent: Boolean(kill),
                            killDisabled: Boolean(kill?.disabled),
                        };
                    })
                    .catch((err) => ({ error: err?.message || String(err) }));

                if (lastOfflineKillSnapshot && lastOfflineKillSnapshot.error) {
                    break;
                }
                if (/Offline kill switch engaged/i.test(lastOfflineKillSnapshot.status)) {
                    break;
                }
                if (/Offline kill switch failed/i.test(lastOfflineKillSnapshot.status)) {
                    await attachJsonSnapshot('offline-kill-compact-final.json', lastCompact);
                    await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
                    appendOfflineKillCiSummary(`- **kill_failed** ${JSON.stringify(lastOfflineKillSnapshot)}`);
                    const err = new Error(
                        `[offline-kill-ci] Offline kill switch failed: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
                    );
                    err.offlineKillClassification = 'post-click-posture-reverted';
                    throw err;
                }
                await page.waitForTimeout(1500);
            }

            await attachJsonSnapshot(
                'offline-kill-compact-final.json',
                lastCompact || (await compactOfflineKillSnapshot(page)),
            );
            await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
            if (!lastOfflineKillSnapshot || lastOfflineKillSnapshot.error) {
                const err = new Error(
                    `[offline-kill-ci] could not read status after click: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
                );
                err.offlineKillClassification = 'post-click-posture-timeout';
                throw err;
            }
            if (!/Offline kill switch engaged/i.test(lastOfflineKillSnapshot.status)) {
                const err = new Error(
                    `[offline-kill-ci] status did not reach engaged within ${STAGE_POSTURE_WAIT_MS / 1000}s: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
                );
                err.offlineKillClassification = 'post-click-posture-timeout';
                throw err;
            }
        },
        {
            extraFailureFields: async () => ({ posturePollSamples: posturePoll.samples }),
            resolveClassification: (err, timedOut) => {
                if (timedOut) return 'post-click-posture-timeout';
                if (err && err.offlineKillClassification === 'post-click-posture-reverted') {
                    return 'post-click-posture-reverted';
                }
                if (err && err.offlineKillClassification === 'post-click-posture-timeout') {
                    return 'post-click-posture-timeout';
                }
                return 'post-click-posture-failed';
            },
        },
    );

    appendOfflineKillCiSummary('- **phase** provider reset to ollama');
    await withCompactOfflineKillDiagnostics('provider-ollama-failed', async () => {
        await expect(providerSelectAfter).toHaveValue('ollama', { timeout: STAGE_RESET_OLLAMA_MS });
    });
    appendOfflineKillCiSummary('- **phase** local-only satisfied (ollama + engaged)');
});

