    let timedOut = false;
    const timeoutPromise = new Promise((_, reject) => {
        timerId = setTimeout(() => {
            timedOut = true;
            reject(new Error(`[offline-kill-prep] ${prepName} exceeded ${timeoutMs}ms`));
