/**
 * Full downstream diagnostics bounded in wall time so prep/stage timeouts can fire and
 * failure snapshots still land without event-loop or storage-scan stalls.
 */
async function offlineKillDiagnosticsSnapshotBestEffort(pg, budgetMs) {
    try {
        return await Promise.race([
            offlineKillDownstreamDiagnostics(pg),
            new Promise((_, reject) => {
                setTimeout(() => {
                    reject(Object.assign(new Error('offline-kill-diagnostics-budget'), { name: 'DiagnosticBudget' }));
                }, budgetMs);
            }),
        ]);
    } catch {
        const compact = await compactOfflineKillSnapshot(pg).catch((e) => ({ error: e?.message || String(e) }));
        return {
            compact,
            downstream: {
                skipped: true,
                reason: 'diagnostics-budget-or-error',
                budgetMs,
            },
        };
    }
}

