async function collectSettingsDrawerCloseDiagnostics(pg) {
    return pg
        .evaluate(() => {
            const norm = (s) => (typeof s === 'string' ? s.trim().slice(0, 500) : '');
            const rectBox = (el) => {
                if (!(el instanceof Element)) return null;
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                return {
                    x: Math.round(r.x),
                    y: Math.round(r.y),
                    w: Math.round(r.width),
                    h: Math.round(r.height),
                    display: st.display,
                    visibility: st.visibility,
                    opacity: st.opacity,
                    pointerEvents: st.pointerEvents,
                    zIndex: st.zIndex,
                    visible:
                        r.width > 0 &&
                        r.height > 0 &&
                        st.visibility !== 'hidden' &&
                        st.display !== 'none' &&
                        Number(st.opacity || '1') > 0,
                };
            };
            const allDrawers = Array.from(document.querySelectorAll('[data-testid="settings-drawer"]'));
            const openDrawers = allDrawers.filter((d) => d.getAttribute('data-state') === 'open');
            const closeButtons = [];
            openDrawers.forEach((drawer, idx) => {
                drawer.querySelectorAll('[data-testid="settings-close-btn"]').forEach((btn) => {
                    closeButtons.push({
                        drawerIndex: idx,
                        disabled: Boolean(btn.disabled),
                        ariaDisabled: btn.getAttribute('aria-disabled'),
                        ...rectBox(btn),
                    });
                });
            });
            const roleCloseMatches = [];
            ['Close', 'Dismiss', 'Cancel'].forEach((name) => {
                document.querySelectorAll('button, [role="button"]').forEach((el) => {
                    const t = norm(el.textContent || '');
                    if (t === name || t.startsWith(`${name} `)) {
                        roleCloseMatches.push({ name, tag: el.tagName, dataTestId: el.getAttribute('data-testid') || '', rect: rectBox(el) });
                    }
                });
            });
            const overlayCandidates = Array.from(
                document.querySelectorAll('[role="dialog"], [aria-modal="true"], [data-testid="session-modal"], [data-testid="command-palette"]'),
            )
                .slice(0, 16)
                .map((el) => ({
                    tag: el.tagName,
                    testid: el.getAttribute('data-testid') || '',
