/**
 * Close the active Settings drawer with bounded clicks, overlay recovery, and CI artifacts.
 * @param {import('@playwright/test').Page} pg
 * @param {import('@playwright/test').TestInfo} _testInfo reserved for future attachment routing
 * @param {string} reasonLabel safe segment for artifact filenames
 */
async function closeActiveSettingsDrawer(pg, _testInfo, reasonLabel) {
    const label = safeSettingsCloseReasonLabel(reasonLabel);
    const base = `settings-drawer-close-${label}`;
    const started = Date.now();

    async function snap() {
        try {
            return await collectSettingsDrawerCloseDiagnostics(pg);
        } catch (err) {
            return { snapshotError: err && err.message ? err.message : String(err) };
        }
    }

    async function writeFailed(classification, err, extra = {}) {
        const elapsedMs = Date.now() - started;
        const drawerSnap = await snap();
        await attachJsonSnapshot(`${base}-failed.json`, {
            classification,
            reasonLabel: label,
            errorName: err && err.name ? err.name : '',
            errorMessage: err && err.message ? err.message : String(err),
            elapsedMs,
            drawerSnapshot: drawerSnap,
            ...extra,
        });
    }

    const openDrawerLocator = pg.locator('[data-testid="settings-drawer"][data-state="open"]:visible');

    let drawer;
    let closeBtn;
    try {
        drawer = await getActiveSettingsDrawer();
        closeBtn = drawer.getByTestId('settings-close-btn');
    } catch (err) {
        await writeFailed('settings-close-drawer-not-closed', err, { phase: 'reacquire-drawer' });
        throw err;
    }

    await attachJsonSnapshot(`${base}-before.json`, {
        classification: 'settings-close-pending',
        reasonLabel: label,
        ...(await snap()),
    });

    const classifyClickErr = (err) => {
        const msg = err && err.message ? err.message : String(err);
        if (/Timeout \d+ms exceeded/i.test(msg)) return 'settings-close-click-timeout';
        if (/intercepts pointer events|not visible|outside viewport/i.test(msg)) return 'settings-close-click-blocked';
        return 'settings-close-click-timeout';
    };

    const assertCloseButtonReady = async () => {
        const count = await closeBtn.count().catch(() => 0);
        if (count === 0) {
            const d = await snap();
            const classification = 'settings-close-button-missing';
            await attachJsonSnapshot(`${base}-failed.json`, {
                classification,
                reasonLabel: label,
                elapsedMs: Date.now() - started,
                drawerSnapshot: d,
            });
            throw new Error(`[settings-drawer-close] ${label}: ${classification}`);
        }
        try {
            await closeBtn.waitFor({ state: 'attached', timeout: 6000 });
        } catch (err) {
            await writeFailed('settings-close-button-missing', err);
            throw err;
        }
        const visible = await closeBtn.isVisible().catch(() => false);
        if (!visible) {
            const d = await snap();
            await attachJsonSnapshot(`${base}-failed.json`, {
                classification: 'settings-close-button-hidden',
                reasonLabel: label,
                elapsedMs: Date.now() - started,
                drawerSnapshot: d,
            });
            throw new Error(`[settings-drawer-close] ${label}: settings-close-button-hidden`);
        }
        const disabled = await closeBtn.isDisabled().catch(() => true);
        const ariaDis = await closeBtn.getAttribute('aria-disabled').catch(() => null);
        if (disabled || ariaDis === 'true') {
            const d = await snap();
            await attachJsonSnapshot(`${base}-failed.json`, {
                classification: 'settings-close-button-disabled',
                reasonLabel: label,
                elapsedMs: Date.now() - started,
                drawerSnapshot: d,
            });
            throw new Error(`[settings-drawer-close] ${label}: settings-close-button-disabled`);
        }
    };

    await assertCloseButtonReady();

    await closeBtn.scrollIntoViewIfNeeded().catch(() => {});

    const confirmDrawerClosed = async () => {
        await expect(openDrawerLocator).toHaveCount(0, { timeout: 8000 });
    };

    const runClick = async (timeoutMs) => {
        await closeBtn.click({ timeout: timeoutMs });
        try {
            await confirmDrawerClosed();
            return true;
        } catch {
            return false;
        }
    };

    let clickOk = false;
    try {
        clickOk = await runClick(8000);
    } catch (err) {
        await writeFailed(classifyClickErr(err), err, { phase: 'first-click' });
        throw err;
    }

    if (!clickOk) {
        await dismissBlockingOverlaysNoBackdrop({ budgetMs: 12000 });
        try {
            drawer = await getActiveSettingsDrawer();
            closeBtn = drawer.getByTestId('settings-close-btn');
        } catch (err) {
            await writeFailed('settings-close-click-not-committed', err, { phase: 'after-first-click-reacquire' });
            throw err;
        }
        await assertCloseButtonReady().catch(() => {});
        await closeBtn.scrollIntoViewIfNeeded().catch(() => {});
        try {
            clickOk = await runClick(6000);
        } catch (err) {
            await writeFailed(classifyClickErr(err), err, { phase: 'second-click-after-overlay-dismiss' });
            throw err;
        }
    }

    if (!clickOk) {
        await pg.keyboard.press('Escape').catch(() => {});
        await pg.waitForTimeout(320);
        const openAfterEscape = await openDrawerLocator.count().catch(() => 1);
        if (openAfterEscape === 0) {
            const d = await snap();
            await attachJsonSnapshot(`${base}-failed.json`, {
                classification: 'settings-close-click-failed-escape-worked',
                reasonLabel: label,
                errorName: 'Error',
                errorMessage: '[settings-drawer-close] primary close clicks did not dismiss drawer; Escape closed it',
                elapsedMs: Date.now() - started,
                drawerSnapshot: d,
            });
            throw new Error(`[settings-drawer-close] ${label}: settings-close-click-failed-escape-worked`);
        }
        const err = new Error(`[settings-drawer-close] ${label}: settings-close-drawer-not-closed`);
        await writeFailed('settings-close-drawer-not-closed', err, { phase: 'after-escape' });
        throw err;
    }

    await attachJsonSnapshot(`${base}-after.json`, {
        classification: 'settings-close-ok',
        reasonLabel: label,
        elapsedMs: Date.now() - started,
        ...(await snap()),
    });
}

