async function selectProviderValue(controls, value, {
    phaseMs,
    label = 'provider',
    selectTimeoutMs = 15000,
} = {}) {
    const timeout = typeof phaseMs === 'number' ? phaseMs : 30000;
    const provider = controls.getByTestId('settings-provider-select');
    await installProviderCommitProbe(page);
    await attachJsonSnapshot(
        `offline-kill-compact-${label}-before-commit-probe.json`,
        await providerStateSnapshot(page, `${label}-before-select`),
    );

    await provider.scrollIntoViewIfNeeded().catch(() => {});

    await withCompactOfflineKillDiagnostics(`${label}-visible-failed`, async () => {
        await expect(provider).toBeVisible({ timeout });
    });

    await withCompactOfflineKillDiagnostics(`${label}-enabled-failed`, async () => {
        await expect(provider).toBeEnabled({ timeout });
    });

    await withCompactOfflineKillDiagnostics(`${label}-select-failed`, async () => {
        await provider.selectOption(value, { timeout: selectTimeoutMs });
    });

    const immediateValue = await provider.evaluate((el) => el.value).catch(() => '');
    await page.waitForTimeout(50);
    const valueAfter50ms = await provider.evaluate((el) => el.value).catch(() => '');
    await page.waitForTimeout(200);
    const valueAfter250ms = await provider.evaluate((el) => el.value).catch(() => '');
    await page.waitForTimeout(750);
    const valueAfter1000ms = await provider.evaluate((el) => el.value).catch(() => '');
    const anyOpenRouter = [immediateValue, valueAfter50ms, valueAfter250ms, valueAfter1000ms].includes(value);

    await withCompactOfflineKillDiagnostics(`${label}-value-failed`, async () => {
        await expect
            .poll(
                async () => provider.evaluate((el) => el.value).catch(() => ''),
                {
                    timeout,
                    intervals: [250, 500, 1000],
                    message: `${label} should become ${value}`,
                },
            )
            .toBe(value);
    });

    if (!anyOpenRouter) {
        const probeSnap = await providerStateSnapshot(page, `${label}-commit-failed-pre-fallback`);
        let classification = 'provider-event-not-fired';
        const controlsFound = Array.isArray(probeSnap.providerControls) ? probeSnap.providerControls : [];
        const providerControls = controlsFound.filter((c) => {
            const blob = `${c.dataTestId || ''} ${c.name || ''} ${c.id || ''} ${c.ariaLabel || ''}`.toLowerCase();
            return blob.includes('provider');
        });
        if (providerControls.length === 0) {
            classification = 'provider-missing';
        } else if (providerControls.some((c) => c.enabled === false)) {
            classification = 'provider-control-disabled';
        } else if (providerControls.length > 1) {
            classification = 'provider-wrong-control-suspected';
        } else if (!Array.isArray(probeSnap.providerEvents) || probeSnap.providerEvents.length === 0) {
            classification = 'provider-event-not-fired';
        }

        await page.evaluate((targetValue) => {
            const sel = document.querySelector('[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]');
            if (!(sel instanceof HTMLSelectElement)) return;
            sel.value = targetValue;
            sel.dispatchEvent(new Event('input', { bubbles: true }));
            sel.dispatchEvent(new Event('change', { bubbles: true }));
        }, value).catch(() => {});
        await page.waitForTimeout(100);
        const fallbackValue = await provider.evaluate((el) => el.value).catch(() => '');
        if (fallbackValue === value) {
            classification = 'playwright-select-path-failed';
        } else {
            const low = JSON.stringify(probeSnap).toLowerCase();
            if (low.includes('offline') || low.includes('local') || low.includes('kill') || low.includes('bridge')) {
                classification = 'provider-local-only-guard-suspected';
            } else {
                classification = 'app-state-reverted-provider';
            }
        }
        await attachJsonSnapshot(
            `offline-kill-compact-${label}-commit-failed.json`,
            {
                classification,
                values: { immediateValue, valueAfter50ms, valueAfter250ms, valueAfter1000ms, fallbackValue },
                probeSnap,
            },
        );
        if (fallbackValue !== value) {
            throw new Error(`[offline-kill-ci] ${label} did not commit ${value} (${classification})`);
        }
        appendOfflineKillCiSummary(`- **provider-commit-fallback** ${label}: ${classification}`);
    }

    return provider;
}

