/** Small payload for offline-kill provider-select artifacts (no unbounded storage walk). */
async function providerSelectMinimalContext(pg = page) {
    return pg
        .evaluate(() => {
            const sel = document.querySelector(
                '[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]',
            );
            if (!(sel instanceof HTMLSelectElement)) {
                return { controlMissing: true, url: location.href };
            }
            const style = window.getComputedStyle(sel);
            const rect = sel.getBoundingClientRect();
            const visible =
                rect.width > 0 &&
                rect.height > 0 &&
                style.display !== 'none' &&
                style.visibility !== 'hidden' &&
                Number(style.opacity || '1') > 0;
            const options = Array.from(sel.options)
                .slice(0, 32)
                .map((o) => ({ value: String(o.value || ''), text: String(o.text || '').trim().slice(0, 160) }));
            const ae = document.activeElement;
            const probe = window.__offlineKillProviderProbe || { events: [] };
            return {
                url: location.href,
                viewport: { width: window.innerWidth, height: window.innerHeight },
                providerValue: String(sel.value || ''),
                options,
                disabled: Boolean(sel.disabled),
                visible,
                activeElement:
                    ae instanceof Element
                        ? {
                              tag: String(ae.tagName || ''),
                              dataTestId: ae.getAttribute('data-testid') || '',
                              id: ae.id || '',
                              value: 'value' in ae ? String(ae.value || '') : '',
                          }
                        : null,
                providerEvents: Array.isArray(probe.events) ? probe.events.slice(-40) : [],
            };
        })
        .catch((err) => ({ evaluateError: err?.message || String(err) }));
}

async function providerStateSnapshotBounded(pg, label, budgetMs) {
    try {
        return await Promise.race([
            providerStateSnapshot(pg, label),
            new Promise((_, reject) => {
                setTimeout(() => reject(Object.assign(new Error('provider-snapshot-budget'), { name: 'Budget' })), budgetMs);
            }),
        ]);
    } catch {
        return { label, bounded: true, skipped: true, reason: 'provider-snapshot-budget-or-error', budgetMs };
    }
}

async function selectProviderValue(controls, value, {
    phaseMs,
    label = 'provider',
    selectTimeoutMs = 15000,
    stageRemainingMsFn = null,
    providerSelectAttempt = 1,
} = {}) {
    const PROVIDER_SELECT_INNER_CAP_MS = 36000;
    const MIN_PROVIDER_SELECT_BUDGET_MS = 4000;
    const CAP_SCROLL_MS = 3000;
    const CAP_VISIBLE_MS = 5000;
    const CAP_ENABLED_MS = 5000;
    const CAP_SELECT_MS = 6000;
    const CAP_POLL_MS = 8000;

    const outerRemaining = () => {
        if (typeof stageRemainingMsFn === 'function') {
            try {
                return Math.max(0, stageRemainingMsFn());
            } catch {
                return PROVIDER_SELECT_INNER_CAP_MS;
            }
        }
        return PROVIDER_SELECT_INNER_CAP_MS + 120000;
    };

    const providerSelectStartedAt = Date.now();
    let providerSelectBudgetMs = Math.min(
        PROVIDER_SELECT_INNER_CAP_MS,
        Math.max(MIN_PROVIDER_SELECT_BUDGET_MS, outerRemaining() - 2500),
    );

    const remainingProviderSelectMs = () => Math.max(0, providerSelectBudgetMs - (Date.now() - providerSelectStartedAt));

    const minTimeout = (cap) => Math.max(400, Math.min(cap, remainingProviderSelectMs()));

    const assertRemaining = (needMs, classification) => {
        if (remainingProviderSelectMs() < needMs) {
            const err = new Error(
                `[offline-kill-ci] provider-select helper budget exhausted (need ${needMs}ms, have ${remainingProviderSelectMs()}ms)`,
            );
            err.providerSelectClassification = classification;
            throw err;
        }
    };

    const useOpenrouterArtifacts = value === 'openrouter';
    const artifactBase = 'offline-kill-provider-select-openrouter';

    const writeOpenrouterArtifact = async (suffix, payload) => {
        if (!useOpenrouterArtifacts) return;
        const elapsedMs = Date.now() - providerSelectStartedAt;
        await attachJsonSnapshot(`${artifactBase}-${suffix}.json`, {
            ...payload,
            elapsedMs,
            providerSelectBudgetMs,
            providerSelectAttempt,
            ...offlineKillBudgetSnapshot(),
        });
    };

    const throwOpenrouterFailed = async (classification, phase, message, extra = {}) => {
        const elapsedMs = Date.now() - providerSelectStartedAt;
        const minimalCtx = await providerSelectMinimalContext(page).catch((e) => ({ error: e?.message || String(e) }));
        const minimal = {
            classification,
            phase,
            errorMessage: message,
            elapsedMs,
            providerSelectBudgetMs,
            providerSelectAttempt,
            targetValue: value,
            ...offlineKillBudgetSnapshot(),
            ...minimalCtx,
            ...extra,
        };
        if (useOpenrouterArtifacts) {
            await attachJsonSnapshot(`${artifactBase}-failed.json`, minimal);
            await attachJsonSnapshot(`${artifactBase}-failed-diagnostics.json`, {
                ...minimal,
                ...(await offlineKillDiagnosticsSnapshotBestEffort(page, 1800)),
                probeBounded: await providerStateSnapshotBounded(page, `${label}-failed-probe`, 1200),
            });
        }
        const err = new Error(`[offline-kill-ci] ${message}`);
        err.providerSelectClassification = classification;
        throw err;
    };

    if (useOpenrouterArtifacts) {
        await writeOpenrouterArtifact('entered.json', {
            classification: 'provider-select-entered',
            phase: 'entered',
        });
    }

    if (page.isClosed()) {
        await throwOpenrouterFailed('provider-select-page-closed', 'page-closed', 'page closed before provider select');
    }

    const provider = controls.getByTestId('settings-provider-select');
    await installProviderCommitProbe(page);

    const ctx0 = await providerSelectMinimalContext(page);
    if (useOpenrouterArtifacts) {
        await writeOpenrouterArtifact('before-select.json', {
            classification: 'provider-select-before-select',
            phase: 'before-select',
            ...ctx0,
        });
    } else {
        await attachJsonSnapshot(
            `offline-kill-compact-${label}-before-commit-probe.json`,
            await providerStateSnapshot(page, `${label}-before-select`),
        );
    }

    const optCheck = await page
        .evaluate((targetValue) => {
            const el = document.querySelector(
                '[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]',
            );
            if (!(el instanceof HTMLSelectElement)) return { ok: false, reason: 'not-select' };
            const has = Array.from(el.options).some((o) => String(o.value) === targetValue);
            return { ok: has, reason: has ? '' : 'option-missing' };
        }, value)
        .catch(() => ({ ok: false, reason: 'evaluate-error' }));
    if (optCheck && optCheck.ok === false && optCheck.reason === 'option-missing') {
        await throwOpenrouterFailed(
            'provider-select-option-missing',
            'option-check',
            `option ${value} missing on provider select`,
            { optionCheck: optCheck },
        );
    }

    assertRemaining(CAP_SCROLL_MS + CAP_VISIBLE_MS + CAP_ENABLED_MS + CAP_SELECT_MS + CAP_POLL_MS, 'provider-select-helper-timeout');

    await provider.scrollIntoViewIfNeeded({ timeout: minTimeout(CAP_SCROLL_MS) }).catch(() => {});

    try {
        assertRemaining(CAP_VISIBLE_MS, 'provider-select-helper-timeout');
        await expect(provider).toBeVisible({ timeout: minTimeout(CAP_VISIBLE_MS) });
    } catch (err) {
        const mini = await providerSelectMinimalContext(page);
        if (mini.controlMissing) {
            await throwOpenrouterFailed('provider-select-control-missing', 'visible', err?.message || String(err), {
                priorError: err?.message || String(err),
            });
        }
        if (mini.visible === false) {
            await throwOpenrouterFailed('provider-select-control-hidden', 'visible', err?.message || String(err), {
                priorError: err?.message || String(err),
            });
        }
        if (useOpenrouterArtifacts) {
            await attachJsonSnapshot(`offline-kill-compact-${label}-visible-failed.json`, await compactOfflineKillSnapshot(page));
        }
        await throwOpenrouterFailed('provider-select-playwright-timeout', 'visible', err?.message || String(err), {
            priorError: err?.message || String(err),
        });
    }

    try {
        assertRemaining(CAP_ENABLED_MS, 'provider-select-helper-timeout');
        await expect(provider).toBeEnabled({ timeout: minTimeout(CAP_ENABLED_MS) });
    } catch (err) {
        const mini = await providerSelectMinimalContext(page);
        if (mini.disabled) {
            await throwOpenrouterFailed('provider-select-control-disabled', 'enabled', err?.message || String(err), {
                priorError: err?.message || String(err),
            });
        }
        if (useOpenrouterArtifacts) {
            await attachJsonSnapshot(`offline-kill-compact-${label}-enabled-failed.json`, await compactOfflineKillSnapshot(page));
        }
        await throwOpenrouterFailed('provider-select-playwright-timeout', 'enabled', err?.message || String(err), {
            priorError: err?.message || String(err),
        });
